import fs from 'node:fs';
import path from 'node:path';
import Fastify from 'fastify';
import cors from '@fastify/cors';
import multipart from '@fastify/multipart';
import fstatic from '@fastify/static';
import { config } from '../config.js';
import publicRoutes from './routes/public.js';
import adminRoutes from './routes/admin.js';
import { ApiError } from '../services/orders.js';

export async function buildServer() {
  const app = Fastify({ logger: { level: 'warn' }, bodyLimit: 1024 * 1024 });

  await app.register(cors, { origin: true });
  await app.register(multipart, {
    limits: { fileSize: config.maxReceiptBytes, files: 1 },
  });

  // Uploaded files (car photos and receipts have unguessable names)
  await app.register(fstatic, {
    root: config.uploadDir,
    prefix: '/uploads/',
    decorateReply: false,
    maxAge: '7d',
    index: false,
    list: false,
  });

  // Same error shape for everything: { error: "code", ...extra }
  app.setErrorHandler((err, req, reply) => {
    // errors we raise on purpose always keep their message (even 502/503)
    if (err instanceof ApiError) return reply.code(err.statusCode).send({ error: err.code, ...err.extra });
    const status = err.statusCode || 500;
    if (status >= 500) {
      req.log.error(err);
      return reply.code(500).send({ error: 'server_error' });
    }
    const code = err.code === 'FST_REQ_FILE_TOO_LARGE' ? 'file_too_large' : err.message;
    reply.code(status).send({ error: code });
  });

  app.register(publicRoutes, { prefix: '/api' });
  app.register(adminRoutes, { prefix: '/api/admin' });

  // Serve the built Mini App (frontend/dist) from the same server
  const dist = config.frontendDist;
  if (fs.existsSync(path.join(dist, 'index.html'))) {
    await app.register(fstatic, { root: dist, prefix: '/', decorateReply: true, wildcard: false, index: ['index.html'] });
    app.setNotFoundHandler((req, reply) => {
      if (req.method === 'GET' && !req.url.startsWith('/api') && !req.url.startsWith('/uploads')) {
        return reply.sendFile('index.html');
      }
      reply.code(404).send({ error: 'not_found' });
    });
  } else {
    console.log('frontend/dist not found - run "npm run build" at the project root to serve the app from here.');
  }
  return app;
}
